class AnnouncementMember { protected String memberId; protected int monthlyFee; protected int sessionsAttended; public AnnouncementMember(String memberId, int monthlyFee) { this.memberId = memberId; this.monthlyFee = monthlyFee; sessionsAttended = 0; } public void attendSession() { sessionsAttended++; } public int getSessionsAttended() { return sessionsAttended; } public String displayInfo() { return "Standard | Sessions: " + sessionsAttended; } }
class AnnouncementPremiumMember extends AnnouncementMember { private String trainerName; public AnnouncementPremiumMember(String memberId, int monthlyFee, String trainerName) { super(memberId, monthlyFee); this.trainerName = trainerName; } public String getTrainerName() { return trainerName; } @Override public String displayInfo() { return "Premium | Trainer: " + trainerName + " | Sessions: " + sessionsAttended; } }
public class AttendanceAnnouncer { public static String batchPrint(AnnouncementMember[] members) { StringBuilder result = new StringBuilder(); for (AnnouncementMember member : members) { result.append(member.displayInfo()); if (member instanceof AnnouncementPremiumMember) { AnnouncementPremiumMember premium = (AnnouncementPremiumMember) member; result.append(" [Trainer via downcast: ").append(premium.getTrainerName()).append("]"); } result.append(" | "); } return result.toString(); } public static void main(String[] args) { AnnouncementMember[] members = {new AnnouncementMember("MEM6", 1000), new AnnouncementPremiumMember("MEM7", 2000, "Coach Riya")}; System.out.println(batchPrint(members)); } }